CLIENT_PRET as (
select CUSTOMER_NO from CLIENT_SOLDE_NAFA
union 
select CUSTOMER_ID as CUSTOMER_NO from CFSFCUBS145.CLTB_ACCOUNT_MASTER  where VALUE_DATE <  TRUNC(SYSDATE, 'MM') ),

ECRITURE_DEBLOCAGE as (

SELECT 
    e.RELATED_ACCOUNT,
    e.AC_NO,
    e.AMOUNT_TAG,
    e.EVENT,
    e.TRN_CODE,
    e.TRN_DT
FROM CFSFCUBS145.acvw_all_ac_entries e
WHERE e.TRN_CODE = '040'
  AND e.AMOUNT_TAG = 'PRINCIPAL'
  AND e.MODULE = 'CL'
  AND e.EVENT = 'DSBR'
  AND e.AC_NO LIKE '251%'
  AND e.TRN_DT >= TRUNC(SYSDATE, 'MM')
  AND e.TRN_DT < ADD_MONTHS(TRUNC(SYSDATE, 'MM'), 1)
)

select 
 c.BRANCH_CODE                                  AS "CODE AGENCE",
  b.branch_name                                  AS "NOM AGENCE",
  c.ACCOUNT_NUMBER                               AS "NO PRET",
  c.CUSTOMER_ID                                  AS "MATRICULE CLIENT",
  c.PRIMARY_APPLICANT_NAME                       AS "NOM CLIENT",
   c.DR_PROD_AC  AS "COMPTE",
c.AMOUNT_FINANCED,
c.FIELD_CHAR_2,
c.UI_DR_PROD_AC,
ec.TRN_DT

FROM CFSFCUBS145.CLTB_ACCOUNT_MASTER c
LEFT JOIN CFSFCUBS145.STTM_BRANCH b
  ON b.branch_code = c.branch_code
join ECRITURE_DEBLOCAGE ec
    on ec.RELATED_ACCOUNT= c.ACCOUNT_NUMBER
    
----left join CLIENT_PRET h on h.CUSTOMER_NO=c.CUSTOMER_ID

where  c.CUSTOMER_ID not in ( select CUSTOMER_NO from CLIENT_PRET);
